import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();
        StringBuilder output = new StringBuilder();
        boolean foundAtSymbol = false;
        int indexCounter = 0;
        while (indexCounter < s.length()) {
            if (indexCounter != 0 && indexCounter + 3 <= s.length() && s.substring(indexCounter, indexCounter + 3).equals("dot")) {
                output.append('.');
                indexCounter += 2;
            } else if (indexCounter != 0 && indexCounter + 2 <= s.length() && !foundAtSymbol && s.substring(indexCounter, indexCounter + 2).equals("at")) {
                output.append('@');
                foundAtSymbol = true;
                indexCounter += 1;
            } else {
                output.append(s.charAt(indexCounter));
            }
            indexCounter += 1;
        }
        System.out.println(output.toString());
    }
}
